B.a5B=s(["Hakam hushtak chaldi \u2013 uchrashuv boshlandi!","O\u2018yin boshlandi. {t} markazdan to\u2018pni harakatga keltirdi.","Stadionda shovqin \u2013 birinchi bo\u2018lim start oldi!"],t.s)
B.a8o=s(["Ikkinchi bo\u2018lim boshlandi. {t} to\u2018pni markazdan surdi.","Jamoalar maydonga qaytdi \u2013 ikkinchi bo\u2018lim ketdi!"],t.s)
B.a7v=s(["GOL! {p} to\u2018rni silkitdi! {s}","GOOOL! {p} darvozabonga imkon qoldirmadi! {s}","GOL! {p} aniq zarba bilan hisobni o\u2018zgartirdi. {s}","{p} \u2014 GOL! {t} muxlislari o\u2018rnidan turib ketdi! {s}"],t.s)
B.a6Y=s(["GOL! {a} uzatmasidan so\u2018ng {p} to\u2018pni darvozaga joyladi! {s}","GOOOL! {a} ajoyib pas berdi, {p} xato qilmadi! {s}","{a} \u2192 {p}: chiroyli kombinatsiya va GOL! {s}"],t.s)
B.a7I=s(["GOL! {p} bosh bilan zarbani darvozaga yo\u2018lladi! {s}","Havodagi kurashda {p} ustun keldi \u2013 GOL! {s}"],t.s)
B.a37=s(["GOL! {p} penaltini ishonch bilan amalga oshirdi. {s}","{p} 11 metrlikdan xato qilmadi \u2013 GOL! {s}"],t.s)
B.a8i=s(["Ajoyib! {p} jarima zarbasini to\u2018g\u2018ridan-to\u2018g\u2018ri darvozaga kiritdi! {s}","GOL! {p} devor ustidan to\u2018pni burchakka yo\u2018lladi! {s}"],t.s)
B.a7o=s(["{p} zarbani ajoyib tarzda qaytardi!","Darvozabon {p} jamoasini qutqarib qoldi.","{p} sakrab to\u2018pni qaytardi.","Aniq zarba, ammo {p} joyida edi."],t.s)
B.a66=s(["{p} to\u2018pni burchakka chiqarib yubordi.","{p} zarbani qaytardi, burchak to\u2018pi tayinlandi."],t.s)
B.a7Z=s(["{p} zarbasi darvoza yonidan o\u2018tib ketdi.","{p} nishonga tegmadi \u2013 to\u2018p tribunaga uchdi.","{p} zarba berdi, ammo to\u2018p darvozadan ancha uzoqda."],t.s)
B.a7b=s(["Qanday imkoniyat! {p} bo\u2018sh darvozaga ham kirita olmadi!","{p} 100 foizlik vaziyatni boy berdi!","Katta imkoniyat \u2013 {p} uni amalga oshira olmadi."],t.s)
B.a7r=s(["USTUN! {p} zarbasi darvoza ustuniga tegdi!","To\u2018sin! {p} omadsizlik qildi."],t.s)
B.a6V=s(["{a} zarbani tanasi bilan to\u2018sib qoldi.","{p} zarbasini {a} blokladi."],t.s)
B.a30=s(["{p} uzoqdan zarba berishga qaror qildi.","{p} darvozani nishonga oldi.","{p} jarima maydoni chetidan zarba yo\u2018lladi."],t.s)
B.a84=s(["{p} bosh bilan zarba berdi.","{p} krossni bosh bilan yo\u2018naltirdi."],t.s)
B.a89=s(["{p} ajoyib Olib qo\u2018yish bilan to\u2018pni oldi.","{p} o\u2018z vaqtida to\u2018pni tortib oldi.","{p} kurashda ustun keldi."],t.s)
B.a7X=s(["{p} uzatmani kesib qoldi.","{p} pas yo\u2018lini to\u2018sib, to\u2018pni egalladi."],t.s)
B.a59=s(["{p} raqibini aldab o\u2018tdi!","{p} chiroyli finti bilan {a}ni ortda qoldirdi.","{p} dribling bilan oldinga yorib o\u2018tdi."],t.s)
B.a6t=s(["{p} jarima maydoniga kross oshirdi.","{p} qanotdan to\u2018pni markazga yubordi."],t.s)
B.a3l=s(["{p} to\u2018pni xavfli hududdan chiqarib tashladi.","{p} havoda ustun kelib, krossni qaytardi."],t.s)
B.a3c=s(["{p} qoidani buzdi. Jarima zarbasi.","Hakam {p}ning qo\u2018pol harakatini qayd etdi.","{p} raqibni ushlab qoldi \u2013 hushtak."],t.s)
B.a3r=s(["{p} sariq kartochka oldi.","Hakam {p}ga sariq kartochka ko\u2018rsatdi.","{p} qo\u2018pollik uchun ogohlantirildi."],t.s)
B.a6a=s(["{p} ikkinchi sariq kartochkani oldi va maydondan chetlatildi!"],t.s)
B.a4D=s(["QIZIL KARTOCHKA! {p} maydonni tark etadi!"],t.s)
B.a54=s(["PENALTI! {a} jarima maydonida {p}ni yiqitdi!","Hakam 11 metrlik nuqtani ko\u2018rsatdi! {p} qulatildi."],t.s)
B.a8b=s(["{a} penaltini qaytardi! {p} uddalay olmadi!","Qaytardi! {a} penaltini to\u2018xtatib qoldi!"],t.s)
B.a6N=s(["{p} penaltini darvoza yonidan o\u2018tkazib yubordi!"],t.s)
B.a4B=s(["{p} jarima zarbasini to\u2018g\u2018ridan-to\u2018g\u2018ri darvozaga yo\u2018lladi.","Standart vaziyat: {p} zarbaga tayyorlanmoqda."],t.s)
B.a5n=s(["Burchak to\u2018pi: {t}.","{t} burchak to\u2018pi ijro etmoqda."],t.s)
B.a4L=s(["Ofsayd: {p}.","Ofsayd: {p} erta harakat qildi."],t.s)
B.a3a=s(["{p} jarohat oldi va yordam so\u2018ramoqda.","{p} oqsoqlanib qoldi \u2013 shifokorlar maydonda."],t.s)
B.a5j=s(["Almashtirish ({t}): {p} maydonga tushdi, {a} chiqdi.","{t}da o\u2018zgarish: {a} o\u2018rniga {p}."],t.s)
B.a7K=s(["Birinchi bo\u2018lim yakunlandi. {s}","Tanaffus. Hisob: {s}"],t.s)
B.a6f=s(["Final hushtagi! Uchrashuv yakunlandi. {s}","O\u2018yin tugadi. Yakuniy hisob: {s}"],t.s)
B.a33=s(["Qo\u2018shimcha vaqt: {p} daqiqa."],t.s)
B.a68=s(['{t} murabbiyi jamoani "{p}" rejimiga o\u2018tkazdi.'],t.s)
